values.CustomCSS:
.bigicon {
  width:auto !important;
    height:auto !important;
  }

.datagrid_title {
color:#222 !important;
font-size:12px !important;
border:none !important;
font-family: Verdana,Helvetica,sans-serif !important;
}

.inventory-row td.data-cell.wrap {
    white-space: normal !important;
}

.inlineDiv {
font-weight: bold;
color: #3498db;
}

#inLineEditForm {
padding:0px !important;
}

#inLineEditForm .fieldarea-field input[type="text"] {
width: auto!important;
}

#inLineEditForm .fieldarea-row {
margin-right: 0 !important;
}

#inLineEditForm .fieldarea-field select, .fieldarea-field select[multiple] {
width: auto!important;
}

.hiddenHeader > .header{
display:none;
}

.hiddenSection {
display:none;
}


.redDiv {
background-color: #C0392B;
font-weight: bold;
color: white;
padding: 5px 2px;
border-radius: 2px;
border: 1px solid #C0392B;
}
.orangeDiv {
background-color: orange;
font-weight: bold;
color: white;
color: #3A3B3C;
padding: 5px 2px;
border-radius: 2px;
border: 1px solid #CC8400;
}
.greenDiv {
background-color: #27AE60;
font-weight: bold;
color: white;
padding: 5px 2px;
border-radius: 2px;
border: 1px solid #27AE60;
}
.yellowDiv {
background-color: #F1C40F;
font-weight: bold;
color: white;
padding: 5px 2px;
border-radius: 2px;
border: 1px solid #F1C40F;
}

.wfDiagram {
	width:100%;
	text-align:center;
	overflow:auto;
	margin-bottom:10px;
}

.wfDiagram > div {
	display: inline-block;
	margin-bottom: 5px;
	padding-left: 24px;
	background-image: url('<%= ImageHelper.GetStaticPath("Icons/new/24x24/navigate_right.gif") %>');
	background-repeat: no-repeat;
	background-position: left center;
}

.wfDiagram > div:first-child {
	padding-left: 0;
	background-image: none;
	position: relative;
}
.wfDiagram > div:last-child {
		margin-bottom: 5px;
	position: relative;
	padding-left: 24px;
	background-image: url('<%= ImageHelper.GetStaticPath("Icons/new/24x24/navigate_right.gif") %>');
         	background-repeat: no-repeat;
	background-position: left center;

}

.wfDiagram > div > div {
	width: 180px;
	text-align: center;
	padding: 6px 2px;
	font-weight: bold;
	border-radius: 8px;
	border: 2px solid #6CC0FF;
	background-color: #FFFFFF;
	color: #3F3F3F;

}

.wfDiagram > div > div[selected='blue'] {
	border: 2px solid #0070C0;
	background-color: #0070C0;
	color: #FFFFFF;
}

.wfDiagram > div > div[selected='red'] {
	border: 2px solid #C0392B;
	background-color: #C0392B;
	color: #FFFFFF;
}

.wfDiagram > div > div[selected='green'] {
	border: 2px solid #27AE60;
	background-color: #27AE60;
	color: #FFFFFF;
}

.wfDiagram > div > div[selected='yellow'] {
	border: 2px solid #F1C40F;
	background-color: #F1C40F;
	color: #FFFFFF;
}

